		public global::Pml.PokePara.WazaLearningResult LearnNewWazaOnLevel(byte level, ref uint sameLevelIndex, ref global::Pml.WazaNo newWazano, global::Pml.PokePara.CoreParam.WazaLearnWork work = null) {
            PersonalSystem.LoadWazaOboeData(GetMonsNo(), GetFormNo());
            var num = PersonalSystem.GetWazaOboeNum();

            uint sameLevelCount = 0;
            for (ushort i = 0; i < num; i++)
            {
                var oboeLevel = PersonalSystem.GetWazaOboeLevel(i);
                var wazano = (WazaNo)PersonalSystem.GetWazaOboeWazaNo(i);
                if (PersonalSystem.GetWazaOboeKind(i) == OboeWazaKind.BASE)
                    continue;

                var isNotChecked = work == null || !work.IsCheckedWaza(wazano);

                if (level < oboeLevel)
                    return WazaLearningResult.FAILED_NOT_EXIST;

                if (level != oboeLevel)
                    continue;

                if (isNotChecked && sameLevelCount == sameLevelIndex)
                {
                    if (work != null)
                        work.AddCheckedWaza(wazano);

                    newWazano = wazano;
                    sameLevelIndex++;
                    return AddWazaIfEmptyExist(wazano);
                }

                sameLevelCount++;
            }

            return WazaLearningResult.FAILED_NOT_EXIST;
        }
