            PersonalSystem.LoadWazaOboeData(GetMonsNo(), GetFormNo());
            var num = PersonalSystem.GetWazaOboeNum();

            for (ushort i = 0; i < num; i++)
            {
                if (PersonalSystem.GetWazaOboeKind(i) == OboeWazaKind.EVOLVE && GetLevel() >= PersonalSystem.GetWazaOboeLevel(i))
                    CheckAndAddWazaNo(wazaList, (WazaNo)PersonalSystem.GetWazaOboeWazaNo(i));
