                    CheckAndAddWazaNo(wazaList, (WazaNo)PersonalSystem.GetWazaOboeWazaNo(i));
            }

            for (ushort i = 0; i < num; i++)
            {
                if (PersonalSystem.GetWazaOboeKind(i) == OboeWazaKind.LEVEL && GetLevel() >= PersonalSystem.GetWazaOboeLevel(i))
                    CheckAndAddWazaNo(wazaList, (WazaNo)PersonalSystem.GetWazaOboeWazaNo(i));
