		public byte GetTokuseiIndex() {
            var isTokusei2 = m_accessor.IsTokusei2();
            var isTokusei3 = m_accessor.IsTokusei3();

            if (isTokusei3)
                return 2;

            return (byte)(isTokusei2 ? 1 : 0);
        }
		public byte GetTokuseiIndexStrict() {
            var flagCount = (byte)((m_accessor.IsTokusei1() ? 1 : 0) + (m_accessor.IsTokusei2() ? 1 : 0) + (m_accessor.IsTokusei3() ? 1 : 0));
            if (flagCount != 1)
                return TOKUSEI_INDEX_ERROR;

            var tokuseiIndex = GetTokuseiIndex();
            var tokuseiNo = (uint)GetTokuseiNo();
            var personal = PersonalSystem.GetPersonalData(GetMonsNo(), GetFormNo());

            if (tokuseiNo == personal.GetParam(ParamID.TOKUSEI1) && tokuseiIndex == 0)
                return 0;

            if (tokuseiNo == personal.GetParam(ParamID.TOKUSEI2) && tokuseiIndex == 1)
                return 1;

            if (tokuseiNo == personal.GetParam(ParamID.TOKUSEI3) && tokuseiIndex == 2)
                return 2;

            return TOKUSEI_INDEX_ERROR;
        }
		public void FlipTokuseiIndex() {
            var tokuseiIndex = GetTokuseiIndex();

            if (tokuseiIndex == 2)
            {
                GFL.ASSERT(false);
                return;
            }

            SetTokuseiIndex((byte)((tokuseiIndex == 1) ? 0 : 1));
        }
		public void SetTokusei3rd() {
            SetTokuseiIndex(2);
        }
		public void SetTokuseiIndex(byte tokuseiIndex) {
            var monsno = GetMonsNo();
            var formno = GetFormNo();

            if (tokuseiIndex > PmlConstants.MAX_TOKUSEI_INDEX)
            {
                GFL.ASSERT(false);
                return;
            }

            var tokuseiNo = CalcTool.GetTokuseiNo(monsno, formno, tokuseiIndex);
            m_accessor.SetTokusei1Flag(tokuseiIndex == 0);
            m_accessor.SetTokusei2Flag(tokuseiIndex == 1);
            m_accessor.SetTokusei3Flag(tokuseiIndex == 2);
            m_accessor.SetTokuseiNo(tokuseiNo);
        }
