		public bool UpdateOwnerInfo(global::Pml.PokePara.OwnerInfo ownerInfo) {
            if (CompareOwnerInfo(ownerInfo))
            {
                m_accessor.SetOwnedOthersFlag(false);
                return true;
            }

            m_accessor.SetOwnedOthersFlag(true);
            SetPastParentsName(ownerInfo.name);
            SetPastParentsSex((Sex)ownerInfo.sex);
            SetPastParentsLangID(ownerInfo.langID);
            m_accessor.SetOthersMemoriesLevel(0);
            m_accessor.SetOthersMemoriesCode(0);
            m_accessor.SetOthersMemoriesData(0);
            m_accessor.SetOthersMemoriesFeel(0);
            m_accessor.SetOthersFriendship((byte)PersonalSystem.GetPersonalData(GetMonsNo(), GetFormNo()).GetParam(ParamID.INITIAL_FRIENDSHIP));
            return false;
        }
