		public void Evolve(global::Pml.MonsNo nextMonsno, uint routeIndex) {
            var monsno = GetMonsNo();
            var formno = GetFormNo();
            PersonalSystem.LoadEvolutionTable(monsno, formno);

            var cond = PersonalSystem.GetEvolutionCondition((byte)routeIndex);
            GFL.ASSERT(PersonalSystem.GetEvolvedMonsNo((byte)routeIndex) == nextMonsno);

            if (PersonalSystem.IsEvolvedFormNoSpecified((byte)routeIndex))
                formno = PersonalSystem.GetEvolvedFormNo((byte)routeIndex);

            ChangeMonsNo(nextMonsno, formno);

            switch (cond)
            {
                case EvolveCond.TUUSHIN_ITEM:
                case EvolveCond.SOUBI_NOON:
                case EvolveCond.SOUBI_NIGHT:
                case EvolveCond.AMEZAIKU:
                    RemoveItem();
                    break;
            }
        }
		public bool CanEvolve(global::Pml.PokePara.EvolveSituation situation, global::Pml.PokeParty party, ref global::Pml.MonsNo nextMonsno, ref uint rootNum) {
            var monsno = GetMonsNo();
            nextMonsno = PmlUse.Instance.GetEvolveManager().GetEvolvedMonsNo_byLevelUp(this, party, situation, ref rootNum);
            return monsno != nextMonsno;
        }
