		protected void changeWazaByFormChange_Forget(global::Pml.WazaNo forgetWaza, global::Pml.WazaNo supplyWaza, global::Pml.PokePara.CoreParam.FormChangeResult pResult = null) {
            if (GetWazaCount() == 1 && GetWazaNo(0) == forgetWaza)
            {
                RemoveWaza(0);
                SetWaza(0, supplyWaza);

                if (pResult != null)
                {
                    pResult.SetRemovedWaza(forgetWaza);
                    pResult.SetAddedWaza(supplyWaza);
                }
            }
            else
            {
                var wazaIndex = GetWazaIndex(forgetWaza);
                if (wazaIndex >= PmlConstants.MAX_WAZA_NUM)
                    return;

                RemoveWaza(wazaIndex);
                CloseUpWazaPos();

                if (pResult != null)
                    pResult.SetRemovedWaza(forgetWaza);
            }
        }
		protected void changeWazaByFormChange_Replace(global::Pml.WazaNo forgetWaza, global::Pml.WazaNo learnWaza, global::Pml.PokePara.CoreParam.FormChangeResult pResult = null) {
            var wazaIndex = GetWazaIndex(forgetWaza);
            if (wazaIndex >= PmlConstants.MAX_WAZA_NUM)
                return;

            var pp = m_accessor.GetPP(wazaIndex);
            m_accessor.SetWazaNo(wazaIndex, (uint)learnWaza);

            var maxPP = GetWazaMaxPP(wazaIndex);
            if (maxPP < pp)
                m_accessor.SetPP(wazaIndex, (byte)maxPP);

            if (pResult != null)
            {
                pResult.SetRemovedWaza(forgetWaza);
                pResult.SetAddedWaza(learnWaza);
            }
        }
